<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { Activity, ArrowRight, BarChart3, Bell, Boxes, CalendarDays, Check, ChevronRight, CircleAlert, Clock3, Download, ImagePlus, Leaf, LogOut, PackageCheck, Plus, Radio, RotateCw, Search, ShieldCheck, ShoppingBag, Sparkles, Store, Tags, Users, WalletCards, X } from '@lucide/vue'
import { download } from '../api.js'
import { localTime, money, orderLabels } from '../domain.js'
import { useMarket } from '../store.js'
import { hasProductImage, productImageFor } from '../productImages.js'
import Sheet from './Sheet.vue'

const props = defineProps({ onBack: { type: Function, required: true }, onLogin: { type: Function, required: true } })
const market = useMarket(), s = market.state
function adminImageError(event, name = event.currentTarget?.alt) { event.currentTarget.onerror = null; event.currentTarget.src = productImageFor(name) }
function applyGeneratedDishImage() { if (!hasProductImage(dishForm.name)) return; dishForm.image = productImageFor(dishForm.name); market.say('已使用匹配配图') }
const pane = ref('overview'), busy = ref(false), notice = ref(''), rows = ref([]), total = ref(0), page = ref(1), pageSize = 10
const dialog = ref(''), detailOrder = ref(null), selectedOrder = ref(null), pendingAction = ref(''), orderReason = ref('')
const categories = ref([]), mealCategories = ref([]), dishes = ref([])
const reportData = reactive({ turnover: null, users: null, orders: null, top: null })
const filters = reactive({ categoryType: 1, categoryName: '', dishName: '', dishCategoryId: '', dishStatus: '', mealName: '', mealCategoryId: '', mealStatus: '', employeeName: '', customerName: '', customerPhone: '', orderNumber: '', phone: '', orderStatus: '', beginTime: '', endTime: '' })
const reportRange = reactive({ begin: localTime(new Date(Date.now() - 6 * 86400000)).slice(0, 10), end: localTime().slice(0, 10) })
const dishForm = reactive({ id: null, name: '', categoryId: '', unit: '', price: '', image: '', description: '', status: 1, flavorsText: '' })
const mealForm = reactive({ id: null, name: '', categoryId: '', price: '', image: '', description: '', status: 1, dishIds: [], copies: {} })
const mealListPrice = computed(() => mealForm.dishIds.reduce((sum, id) => { const dish = dishes.value.find(item => Number(item.id) === Number(id)); return sum + Number(dish?.price || 0) * Number(mealForm.copies[id] || 1) }, 0))
const mealSalePrice = computed(() => Math.round((mealListPrice.value * 0.95 + Number.EPSILON) * 100) / 100)
const categoryForm = reactive({ id: null, name: '', type: 1, sort: 1, status: 1 })
const employeeForm = reactive({ id: null, username: '', name: '', phone: '', sex: '1', idNumber: '' })
const saleForm = reactive({ id: null, activityName: '', dishId: '', salePrice: '', stock: 50, limitPerUser: 1, startTime: '', endTime: '', status: 0 })
const agent = reactive({ query: '', loading: false, result: null, error: '' })
const nav = [
  { id: 'overview', name: '工作台', icon: Leaf }, { id: 'orders', name: '订单管理', icon: PackageCheck },
  { id: 'goods', name: '菜品管理', icon: Boxes }, { id: 'setmeals', name: '套餐管理', icon: ShoppingBag },
  { id: 'categories', name: '分类管理', icon: Tags }, { id: 'employees', name: '员工管理', icon: Users },
  { id: 'customers', name: '客户档案', icon: Users },
  { id: 'sales', name: '限时特卖', icon: Clock3 }, { id: 'reports', name: '数据统计', icon: BarChart3 },
  { id: 'assistant', name: '经营参谋', icon: Sparkles },
]
const title = computed(() => nav.find(item => item.id === pane.value)?.name || '工作台')
const reportSeries = computed(() => ({ turnover: split(reportData.turnover?.turnoverList), users: split(reportData.users?.newUserList), orders: split(reportData.orders?.orderCountList) }))
const reportDates = computed(() => split(reportData.turnover?.dateList, false))
const topRows = computed(() => split(reportData.top?.nameList, false).map((name, index) => ({ name, value: Number(split(reportData.top?.numberList)[index] || 0) })))
function split(value, numeric = true) { if (!value) return []; const parts = String(value).split(','); return numeric ? parts.map(Number) : parts }
function points(values, height = 120) { if (!values.length) return ''; const max = Math.max(...values, 1); return values.map((value, index) => (values.length < 2 ? 300 : 8 + index * 584 / (values.length - 1)) + ',' + (height - 8 - Number(value || 0) / max * (height - 20))).join(' ') }
function fmt(value) { return money(value) }
function orderNo(row) { return row.number || row.orderNumber || ('#' + row.id) }
function itemSummary(row) { return row.orderDishes || (row.orderDetailList || []).map(item => (item.name || '鲜品') + ' × ' + item.number).join('、') || '—' }
function dateInput(offset) { return localTime(new Date(Date.now() + offset)).slice(0, 16) }
function resetOrderFilters() { Object.assign(filters, { orderNumber: '', phone: '', orderStatus: '', beginTime: '', endTime: '' }) }
function route(id) { pane.value = id; page.value = 1; notice.value = ''; if (id === 'orders') resetOrderFilters(); loadPane() }
function handleLiveOrderUpdate(event) { if (pane.value !== 'orders') return; if (Number(event.detail?.type) === 1) resetOrderFilters(); page.value = 1; loadPane() }
async function toggleMode() { await market.setMode(s.mode === 'demo' ? 'live' : 'demo'); await market.refreshAdmin() }
function setRows(data) { rows.value = data?.records || []; total.value = Number(data?.total || 0) }
async function loadPane() {
  busy.value = true; notice.value = ''
  try {
    if (pane.value === 'overview') { await market.refreshAdmin(); return }
    if (s.mode === 'demo') { loadDemoPane(); return }
    if (!s.adminToken) return
    if (pane.value === 'categories') {
      const result = await market.adminRequest('/admin/category/page?page=' + page.value + '&pageSize=' + pageSize + '&type=' + filters.categoryType + (filters.categoryName ? '&name=' + encodeURIComponent(filters.categoryName) : ''))
      setRows(result)
    } else if (pane.value === 'goods') {
      const [result, cats] = await Promise.all([market.adminRequest('/admin/dish/page?page=' + page.value + '&pageSize=' + pageSize + (filters.dishName ? '&name=' + encodeURIComponent(filters.dishName) : '') + (filters.dishCategoryId ? '&categoryId=' + filters.dishCategoryId : '') + (filters.dishStatus !== '' ? '&status=' + filters.dishStatus : '')), market.adminRequest('/admin/category/list?type=1')])
      setRows(result); categories.value = cats || []; s.adminProducts = result?.records || []
    } else if (pane.value === 'setmeals') {
      const [result, cats, activeDishes] = await Promise.all([market.adminRequest('/admin/setmeal/page?page=' + page.value + '&pageSize=' + pageSize + (filters.mealName ? '&name=' + encodeURIComponent(filters.mealName) : '') + (filters.mealCategoryId ? '&categoryId=' + filters.mealCategoryId : '') + (filters.mealStatus !== '' ? '&status=' + filters.mealStatus : '')), market.adminRequest('/admin/category/list?type=2'), loadActiveDishes()])
      setRows(result); mealCategories.value = cats || []; dishes.value = activeDishes; s.adminSetmeals = result?.records || []
    } else if (pane.value === 'employees') setRows(await market.adminRequest('/admin/employee/page?page=' + page.value + '&pageSize=' + pageSize + (filters.employeeName ? '&name=' + encodeURIComponent(filters.employeeName) : '')))
    else if (pane.value === 'customers') {
      const query = new URLSearchParams({ page: String(page.value), pageSize: String(pageSize) })
      if (filters.customerName) query.set('name', filters.customerName)
      if (filters.customerPhone) query.set('phone', filters.customerPhone)
      setRows(await market.adminRequest('/admin/customer/page?' + query.toString()))
    }
    else if (pane.value === 'orders') {
      const query = new URLSearchParams({ page: String(page.value), pageSize: String(pageSize) })
      if (filters.orderNumber) query.set('number', filters.orderNumber)
      if (filters.phone) query.set('phone', filters.phone)
      if (filters.orderStatus !== '') query.set('status', filters.orderStatus)
      if (filters.beginTime) query.set('beginTime', filters.beginTime.replace('T', ' ') + ':00')
      if (filters.endTime) query.set('endTime', filters.endTime.replace('T', ' ') + ':59')
      const [result, stats] = await Promise.all([market.adminRequest('/admin/order/conditionSearch?' + query.toString()), market.adminRequest('/admin/order/statistics')])
      setRows(result); s.orderStats = stats || {}
    } else if (pane.value === 'sales') {
      const [result, activeDishes] = await Promise.all([market.adminRequest('/admin/flashsale/page?page=' + page.value + '&pageSize=' + pageSize), loadActiveDishes()])
      setRows(result); s.adminActivities = result?.records || []; dishes.value = activeDishes
    } else if (pane.value === 'reports') await loadReports()
  } catch (error) { notice.value = error.message } finally { busy.value = false }
}
async function loadActiveDishes() {
  if (s.mode === 'demo') return market.demo.products().filter(dish => dish.status === 1)
  const categories = await market.adminRequest('/admin/category/list?type=1')
  const groups = await Promise.all((categories || []).map(category => market.adminRequest('/admin/dish/list?categoryId=' + category.id)))
  return groups.flat()
}
function loadDemoPane() {
  if (pane.value === 'categories') { rows.value = market.demo.categories(filters.categoryType).filter(row => !filters.categoryName || row.name.includes(filters.categoryName)); total.value = rows.value.length }
  else if (pane.value === 'goods') { categories.value = market.demo.categories(1); rows.value = market.demo.products().filter(row => (!filters.dishName || row.name.includes(filters.dishName)) && (!filters.dishCategoryId || Number(row.categoryId) === Number(filters.dishCategoryId)) && (filters.dishStatus === '' || Number(row.status) === Number(filters.dishStatus))); total.value = rows.value.length; s.adminProducts = rows.value }
  else if (pane.value === 'setmeals') { mealCategories.value = market.demo.categories(2); dishes.value = market.demo.products().filter(row => row.status === 1); rows.value = market.demo.setmeals().filter(row => (!filters.mealName || row.name.includes(filters.mealName)) && (!filters.mealCategoryId || Number(row.categoryId) === Number(filters.mealCategoryId)) && (filters.mealStatus === '' || Number(row.status) === Number(filters.mealStatus))); total.value = rows.value.length; s.adminSetmeals = rows.value }
  else if (pane.value === 'employees') { rows.value = market.demo.employees().filter(row => !filters.employeeName || row.name.includes(filters.employeeName)); total.value = rows.value.length }
  else if (pane.value === 'customers') { rows.value = market.demo.customers().filter(row => (!filters.customerName || row.name.includes(filters.customerName)) && (!filters.customerPhone || String(row.phone || '').includes(filters.customerPhone))); total.value = rows.value.length }
  else if (pane.value === 'orders') { rows.value = market.demo.orders().filter(row => (!filters.orderNumber || orderNo(row).includes(filters.orderNumber)) && (!filters.phone || String(row.phone || '').includes(filters.phone)) && (filters.orderStatus === '' || Number(row.status) === Number(filters.orderStatus))); total.value = rows.value.length }
  else if (pane.value === 'sales') { rows.value = market.demo.activities(); total.value = rows.value.length; dishes.value = market.demo.products().filter(row => row.status === 1); s.adminActivities = rows.value }
  else if (pane.value === 'reports') loadDemoReports()
}
function loadDemoReports() {
  const orders = market.demo.orders(), complete = orders.filter(row => row.status === 5)
  const products = market.demo.products()
  const days = Array.from({ length: 7 }, (_, index) => localTime(new Date(Date.now() - (6 - index) * 86400000)).slice(0, 10))
  reportData.turnover = { dateList: days.join(','), turnoverList: days.map(day => complete.filter(order => String(order.orderTime).slice(0, 10) === day).reduce((sum, order) => sum + Number(order.amount || 0), 0)).join(',') }
  reportData.users = { dateList: days.join(','), totalUserList: days.map((_, index) => index + 1).join(','), newUserList: days.map(() => 0).join(',') }
  reportData.orders = { dateList: days.join(','), orderCountList: days.map(day => orders.filter(order => String(order.orderTime).slice(0, 10) === day).length).join(','), validOrderCountList: days.map(day => complete.filter(order => String(order.orderTime).slice(0, 10) === day).length).join(','), totalOrderCount: orders.length, validOrderCount: complete.length, orderCompletionRate: orders.length ? complete.length / orders.length : 0 }
  reportData.top = { nameList: products.map(row => row.name).join(','), numberList: products.map(product => orders.reduce((sum, order) => sum + (order.orderDetailList || []).filter(item => Number(item.dishId) === Number(product.id)).reduce((n, item) => n + Number(item.number || 0), 0), 0)).join(',') }
}
async function loadReports() {
  const query = '?begin=' + reportRange.begin + '&end=' + reportRange.end
  const [turnover, users, orders, top] = await Promise.all([market.adminRequest('/admin/report/turnoverStatistics' + query), market.adminRequest('/admin/report/userStatistics' + query), market.adminRequest('/admin/report/ordersStatistics' + query), market.adminRequest('/admin/report/top10' + query)])
  reportData.turnover = turnover; reportData.users = users; reportData.orders = orders; reportData.top = top
}
async function refreshData() { if (pane.value === 'overview') await market.refreshAdmin(); else await loadPane() }
function openCategory(value) { Object.assign(categoryForm, value ? { ...value } : { id: null, name: '', type: filters.categoryType, sort: 1, status: 1 }); dialog.value = 'category' }
async function saveCategory() { const value = { ...categoryForm, type: Number(categoryForm.type), sort: Number(categoryForm.sort) }; if (s.mode === 'demo') market.demo.saveCategory(value); else await market.adminRequest('/admin/category', { method: value.id ? 'PUT' : 'POST', body: value }); dialog.value = ''; await loadPane() }
async function deleteCategory(row) { if (!window.confirm('删除分类“' + row.name + '”？')) return; if (s.mode === 'demo') market.demo.deleteCategory(row.id); else await market.adminRequest('/admin/category?id=' + row.id, { method: 'DELETE' }); await loadPane() }
async function toggleCategory(row) { if (s.mode === 'demo') market.demo.toggleCategory(row.id); else await market.adminRequest('/admin/category/status/' + (row.status ? 0 : 1) + '?id=' + row.id, { method: 'POST' }); await loadPane() }
function openDish(value) { Object.assign(dishForm, value ? { ...value, flavorsText: (value.flavors || []).map(item => item.name + '=' + item.value).join('\n') } : { id: null, name: '', categoryId: categories.value[0]?.id || '', unit: '', price: '', image: '', description: '', status: 1, flavorsText: '' }); dialog.value = 'dish' }
async function editDish(row) { openDish(s.mode === 'demo' ? market.demo.product(row.id) : await market.adminRequest('/admin/dish/' + row.id)) }
async function uploadDishImage(event) { const file = event.target.files?.[0]; if (!file) return; try { busy.value = true; dishForm.image = await market.uploadImage(file); market.say('图片上传完成') } catch (error) { notice.value = error.message } finally { busy.value = false; event.target.value = '' } }
async function saveDish() {
  const flavors = dishForm.flavorsText.split('\n').map(line => line.trim()).filter(Boolean).map(line => { const parts = line.split('='); return { name: parts[0].trim(), value: (parts.slice(1).join('=') || '').trim() } })
  const value = { id: dishForm.id, name: dishForm.name.trim(), categoryId: Number(dishForm.categoryId), unit: dishForm.unit.trim(), price: Number(dishForm.price), image: dishForm.image, description: dishForm.description, status: Number(dishForm.status), flavors }
  if (s.mode === 'demo') market.demo.saveProduct(value); else await market.adminRequest('/admin/dish', { method: value.id ? 'PUT' : 'POST', body: value })
  dialog.value = ''; await loadPane()
}
async function toggleDish(row) { if (s.mode === 'demo') market.demo.toggleProduct(row.id); else await market.adminRequest('/admin/dish/status/' + (row.status ? 0 : 1) + '?id=' + row.id, { method: 'POST' }); await loadPane() }
async function deleteDish(row) { if (!window.confirm('删除菜品“' + row.name + '”？历史关联菜品无法删除。')) return; if (s.mode === 'demo') market.demo.deleteProduct(row.id); else await market.adminRequest('/admin/dish?ids=' + row.id, { method: 'DELETE' }); await loadPane() }
function openMeal(value) {
  const meal = value || { id: null, name: '', categoryId: mealCategories.value[0]?.id || '', price: '', image: '', description: '', status: 1, setmealDishes: [] }
  Object.assign(mealForm, { id: meal.id || null, name: meal.name || '', categoryId: meal.categoryId || '', price: meal.price || '', image: meal.image || '', description: meal.description || '', status: meal.status ?? 1, dishIds: (meal.setmealDishes || []).map(item => Number(item.dishId)), copies: Object.fromEntries((meal.setmealDishes || []).map(item => [item.dishId, item.copies || 1])) })
  dialog.value = 'meal'
}
async function editMeal(row) { openMeal(s.mode === 'demo' ? market.demo.setmeal(row.id) : await market.adminRequest('/admin/setmeal/' + row.id)) }
async function saveMeal() {
  const setmealDishes = mealForm.dishIds.map(id => { const dish = dishes.value.find(item => Number(item.id) === Number(id)); return { dishId: Number(id), name: dish?.name || '', price: Number(dish?.price || 0), copies: Number(mealForm.copies[id] || 1) } })
  if (!setmealDishes.length) { notice.value = '至少选择一款菜品加入套餐。'; return }
  const value = { id: mealForm.id, categoryId: Number(mealForm.categoryId), name: mealForm.name.trim(), price: mealSalePrice.value, image: mealForm.image, description: mealForm.description, status: Number(mealForm.status), setmealDishes }
  if (s.mode === 'demo') market.demo.saveSetmeal(value); else await market.adminRequest('/admin/setmeal', { method: value.id ? 'PUT' : 'POST', body: value })
  dialog.value = ''; await loadPane()
}
async function uploadMealImage(event) { const file = event.target.files?.[0]; if (!file) return; try { busy.value = true; mealForm.image = await market.uploadImage(file); market.say('套餐图片上传完成') } catch (error) { notice.value = error.message } finally { busy.value = false; event.target.value = '' } }
async function toggleMeal(row) { if (s.mode === 'demo') market.demo.toggleSetmeal(row.id); else await market.adminRequest('/admin/setmeal/status/' + (row.status ? 0 : 1) + '?id=' + row.id, { method: 'POST' }); await loadPane() }
async function deleteMeal(row) { if (!window.confirm('删除套餐“' + row.name + '”？')) return; if (s.mode === 'demo') market.demo.deleteSetmeal(row.id); else await market.adminRequest('/admin/setmeal?ids=' + row.id, { method: 'DELETE' }); await loadPane() }
function openEmployee(value) { Object.assign(employeeForm, value ? { ...value } : { id: null, username: '', name: '', phone: '', sex: '1', idNumber: '' }); dialog.value = 'employee' }
async function editEmployee(row) { openEmployee(s.mode === 'demo' ? row : await market.adminRequest('/admin/employee/' + row.id)) }
async function saveEmployee() { const value = { id: employeeForm.id, username: employeeForm.username.trim(), name: employeeForm.name.trim(), phone: employeeForm.phone.trim(), sex: employeeForm.sex, idNumber: employeeForm.idNumber.trim() }; if (s.mode === 'demo') market.demo.saveEmployee(value); else await market.adminRequest('/admin/employee', { method: value.id ? 'PUT' : 'POST', body: value }); dialog.value = ''; await loadPane() }
async function toggleEmployee(row) { if (s.mode === 'demo') market.demo.toggleEmployee(row.id); else await market.adminRequest('/admin/employee/status/' + (row.status ? 0 : 1) + '?id=' + row.id, { method: 'POST' }); await loadPane() }
function openSale(value) {
  const sale = value || { id: null, activityName: '', dishId: '', salePrice: '', stock: 50, limitPerUser: 1, startTime: dateInput(-3600000), endTime: dateInput(86400000), status: 0 }
  Object.assign(saleForm, { ...sale, id: sale.id || null, dishId: sale.dishId || '', startTime: sale.startTime ? String(sale.startTime).replace(' ', 'T').slice(0, 16) : dateInput(-3600000), endTime: sale.endTime ? String(sale.endTime).replace(' ', 'T').slice(0, 16) : dateInput(86400000) }); dialog.value = 'sale'
}
async function editSale(row) { openSale(s.mode === 'demo' ? row : await market.adminRequest('/admin/flashsale/' + row.id)) }
async function saveSale() { const value = { ...saleForm, dishId: Number(saleForm.dishId), salePrice: Number(saleForm.salePrice), stock: Number(saleForm.stock), limitPerUser: Number(saleForm.limitPerUser), startTime: saleForm.startTime.replace('T', ' ') + ':00', endTime: saleForm.endTime.replace('T', ' ') + ':00', status: Number(saleForm.status) }; await market.saveActivity(value); dialog.value = ''; await loadPane() }
async function toggleSale(row) { await market.toggleActivity(row); await loadPane() }
async function preheatSale(row) { await market.preheat(row); await loadPane() }
async function orderDetails(row) { detailOrder.value = await market.orderDetail(row, true); dialog.value = 'orderDetail' }
function requestOrderAction(row, action) { if (action === 'reject' || action === 'cancel') { selectedOrder.value = row; pendingAction.value = action; orderReason.value = ''; dialog.value = 'orderReason'; return } performOrderAction(row, action) }
async function performOrderAction(row, action, reason = '') { await market.orderAction(row, action, true, reason); dialog.value = ''; await loadPane() }
async function submitReason() { await performOrderAction(selectedOrder.value, pendingAction.value, orderReason.value.trim()) }
async function exportReport() { try { const file = await download('/admin/report/export', { token: s.adminToken, admin: true }); const url = URL.createObjectURL(file.blob), link = document.createElement('a'); link.href = url; link.download = '鲜集经营数据报表.xlsx'; link.click(); URL.revokeObjectURL(url) } catch (error) { notice.value = error.message } }
async function analyze() {
  if (!agent.query.trim() || agent.loading) return
  agent.loading = true; agent.error = ''; agent.result = null
  try {
    if (s.mode === 'demo') { agent.result = { summary: '演示数据已准备。连接门店数据后，即可查看实时营业指标。', analysis: ['经营概览含营业额、有效订单、平均客单价与完成率。'], suggestions: ['可继续询问销售趋势、品类结构、热销商品或订单状态。'], toolCalls: ['demo-workspace'] }; return }
    const body = { traceId: crypto.randomUUID(), query: agent.query.trim(), timeRange: { startTime: reportRange.begin + 'T00:00:00', endTime: reportRange.end + 'T23:59:59' }, compareRange: null, context: { role: 'merchant_admin', timezone: 'Asia/Shanghai' } }
    const response = await fetch('/agent/ops/analyze', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
    const data = await response.json()
    if (!response.ok) throw new Error(data.detail || '经营参谋暂不可用，请稍后重试。')
    agent.result = data
  } catch (error) { agent.error = error.message } finally { agent.loading = false }
}
function logout() { market.logoutAdmin().then(props.onBack).catch(error => { notice.value = error.message }) }
onMounted(() => { window.addEventListener('fresh-order-update', handleLiveOrderUpdate); pane.value === 'overview' ? market.refreshAdmin() : loadPane() })
onBeforeUnmount(() => window.removeEventListener('fresh-order-update', handleLiveOrderUpdate))
</script>

<template>
  <div class="merchant-experience admin-suite">
    <aside class="admin-nav">
      <button class="brand brand--admin" @click="props.onBack"><span class="brand__mark"><Leaf :size="20"/></span><span class="brand__text"><strong>鲜集 <span>FRESH</span></strong><small>社区鲜食经营中心</small></span></button>
      <div class="admin-merchant"><span class="avatar avatar--shop"><Store :size="17"/></span><span><strong>鲜集社区店</strong><small>北京 · 朝阳门店</small></span><i class="live-dot"/></div>
      <span class="aside-label">经营管理 <i>STORE OPS</i></span>
      <nav class="admin-nav__items" aria-label="商家管理模块"><button v-for="item in nav" :key="item.id" :class="['admin-nav__item',{ 'is-active':pane===item.id }]" @click="route(item.id)"><component :is="item.icon" :size="16"/><span>{{ item.name }}</span><span v-if="item.id==='orders'&&s.orderStats.toBeConfirmed" class="nav-count">{{ s.orderStats.toBeConfirmed }}</span></button></nav>
      <div class="admin-nav__bottom"><div class="manager-card"><div class="manager-card__top"><span>工作台状态</span><Radio :size="14" :class="s.mode==='demo'||s.wsConnected?'icon-live':'icon-muted'"/></div><b>{{ s.mode==='demo'?'演示工作台':s.wsConnected?'实时提醒已连接':'实时提醒连接中' }}</b><small>{{ s.mode==='demo'?'数据保存在当前浏览器':s.wsConnected?'可接收新订单提醒':'订单提醒连接中' }}</small></div><button class="admin-account" @click="s.adminToken?logout():props.onLogin()"><span class="avatar">林</span><span><b>{{ s.adminToken?'退出工作台':'商家登录' }}</b><small>{{ s.adminToken?'结束当前管理会话':'使用员工账号登录' }}</small></span><LogOut :size="16" class="admin-account__exit"/></button></div>
    </aside>
    <main class="admin-main">
      <header class="admin-topbar"><span class="admin-topbar__title"><span class="eyebrow">FRESH MARKET</span><b>{{ title }}</b></span><div class="admin-topbar__tools"><button class="btn btn--soft btn--sm admin-mode-switch" @click="toggleMode()">{{ s.mode==='demo'?'连接门店数据':'切到演示数据' }}</button><span :class="['store-status',s.shopStatus?'':'store-status--closed']"><i/>{{ s.shopStatus?'营业中':'已打烊' }}</span><button class="btn btn--soft btn--sm" :disabled="s.mode==='live'&&!s.adminToken" @click="market.toggleShop()">{{ s.shopStatus?'暂停接单':'恢复营业' }}</button><button class="btn btn--bare btn--sm admin-session-action" @click="s.adminToken?logout():props.onLogin()">{{ s.adminToken?'退出登录':'商家登录' }}</button><button class="icon-button" aria-label="返回顾客前台" @click="props.onBack"><X :size="17"/></button></div></header>
      <div v-if="s.mode==='live'&&!s.adminToken" class="admin-page"><section class="manager-gate"><span class="manager-gate__icon"><ShieldCheck :size="22"/></span><span class="eyebrow">MERCHANT ACCESS</span><h2>商家登录后即可管理门店</h2><p>使用员工账号登录，即可管理订单、商品、员工和经营报表。</p><button class="btn btn--primary" @click="props.onLogin()">登录商家账号 <ArrowRight :size="15"/></button></section></div>
      <div v-else class="admin-page">
        <div v-if="notice||s.error" class="admin-alert"><CircleAlert :size="17"/>{{ notice||s.error }}<button class="bare" @click="loadPane"><RotateCw :size="15"/> 重试</button></div>
        <section class="admin-heading"><div><span class="eyebrow">{{ title.toUpperCase() }} · 鲜集经营</span><h1>{{ pane==='overview'?'今天，生意正新鲜。':title }}</h1><p>{{ pane==='overview'?'商品、订单和门店状态，一眼掌握。':'每一份新鲜，都从仔细经营开始。' }}</p></div><div class="heading-actions"><button class="btn btn--soft btn--sm" :disabled="busy" @click="pane==='overview'?market.refreshAdmin():loadPane()"><RotateCw :size="15" :class="{spin:busy}"/> 更新数据</button><button v-if="['goods','setmeals','categories','employees','sales'].includes(pane)" class="btn btn--primary btn--sm" @click="pane==='goods'?openDish():pane==='setmeals'?openMeal():pane==='categories'?openCategory():pane==='employees'?openEmployee():openSale()"><Plus :size="15"/> {{ pane==='goods'?'新增菜品':pane==='setmeals'?'新增套餐':pane==='categories'?'新增分类':pane==='employees'?'新增员工':'创建特卖' }}</button></div></section>

        <template v-if="pane==='overview'">
          <div class="stats-grid">
            <article class="stat-card"><span>今日营业额</span><strong>¥{{ fmt(s.metrics.turnover) }}</strong><small><WalletCards :size="13"/> 经营收入</small><span class="stat-icon"><WalletCards :size="17"/></span></article>
            <article class="stat-card"><span>有效订单</span><strong>{{ s.metrics.validOrderCount||0 }}</strong><small><PackageCheck :size="13"/> 今日已完成</small><span class="stat-icon"><ShoppingBag :size="17"/></span></article>
            <article class="stat-card"><span>平均客单价</span><strong>¥{{ fmt(s.metrics.unitPrice) }}</strong><small><Activity :size="13"/> 完成率 {{ Math.round((s.metrics.orderCompletionRate||0)*100) }}%</small><span class="stat-icon"><Activity :size="17"/></span></article>
            <article class="stat-card"><span>新增顾客</span><strong>{{ s.metrics.newUsers||0 }}</strong><small><Users :size="13"/> 今日首次到店</small><span class="stat-icon"><Users :size="17"/></span></article>
          </div>
          <div class="stats-grid stats-grid--compact"><button class="stat-card stat-card--link" @click="route('orders')"><span>待接单</span><strong>{{ s.workspace.orderOverview?.waitingOrders||0 }}</strong><small>订单管理 <ArrowRight :size="12"/></small></button><button class="stat-card stat-card--link" @click="route('orders')"><span>待配送</span><strong>{{ s.orderStats.deliveryInProgress||0 }}</strong><small>订单履约 <ArrowRight :size="12"/></small></button><button class="stat-card stat-card--link" @click="route('goods')"><span>在售菜品</span><strong>{{ s.workspace.dishOverview?.sold||0 }}</strong><small>菜品管理 <ArrowRight :size="12"/></small></button><button class="stat-card stat-card--link" @click="route('setmeals')"><span>在售套餐</span><strong>{{ s.workspace.setmealOverview?.sold||0 }}</strong><small>套餐管理 <ArrowRight :size="12"/></small></button></div>
          <div class="admin-overview-grid"><section class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">ORDER FULFILLMENT</span><h2>最新订单</h2></div><button class="text-link" @click="route('orders')">全部订单 <ChevronRight :size="14"/></button></div><div v-if="s.adminOrders.length" class="orders-queue"><article v-for="order in s.adminOrders.slice(0,6)" :key="order.id" class="queue-row"><div class="queue-mark"><ShoppingBag :size="16"/></div><div class="queue-info"><b>{{ orderNo(order) }}</b><small>{{ order.consignee||'顾客' }} · {{ orderLabels[order.status]||'处理中' }}</small></div><span class="queue-total">¥{{ fmt(order.amount) }}</span><button class="btn btn--soft btn--sm" @click="orderDetails(order)">详情</button></article></div><div v-else class="quiet-empty"><span class="quiet-empty__icon"><Check :size="18"/></span><div><b>暂时没有新订单</b><small>顾客下单后会显示在这里。</small></div></div></section>
            <section class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">LIVE STORE STATUS</span><h2>门店经营状态</h2></div><Store :size="18" class="icon-live"/></div><div class="status-overview"><span :class="['status-pip',s.shopStatus?'status-pip--green':'']"/><div><b>{{ s.shopStatus?'正在营业，正常接单':'门店已打烊' }}</b><small>顾客下单和特卖活动遵循当前营业状态。</small></div><button class="btn btn--soft btn--sm" @click="market.toggleShop()">{{ s.shopStatus?'暂停营业':'开始营业' }}</button></div><div class="overview-shortcuts"><button @click="route('categories')"><Tags :size="15"/> 分类 <ChevronRight :size="13"/></button><button @click="route('employees')"><Users :size="15"/> 员工 <ChevronRight :size="13"/></button><button @click="route('reports')"><BarChart3 :size="15"/> 经营报表 <ChevronRight :size="13"/></button></div></section></div>
          <section class="admin-panel recent-panel"><div class="panel-heading"><div><span class="eyebrow">REAL-TIME EVENTS</span><h2>订单提醒 <small>{{ s.mode==='demo'?'演示事件':s.wsConnected?'实时提醒已连接':'等待实时提醒' }}</small></h2></div><Bell :size="17"/></div><div v-if="s.messages.length" class="event-list"><div v-for="(message,index) in s.messages.slice(0,5)" :key="index"><i/>{{ message.content||'收到订单事件' }}<time>{{ message.time }}</time></div></div><p v-else class="subtle-copy">商家登录后可在此查看催单和订单状态提醒。</p></section>
        </template>

        <template v-else-if="pane==='categories'">
          <section class="admin-panel module-panel"><div class="module-toolbar"><div class="filter-row"><label>分类类型<select v-model.number="filters.categoryType" @change="page=1;loadPane()"><option :value="1">菜品分类</option><option :value="2">套餐分类</option></select></label><label>分类名称<input v-model="filters.categoryName" placeholder="搜索分类" @keyup.enter="page=1;loadPane()"/></label><button class="btn btn--soft btn--sm" @click="page=1;loadPane()"><Search :size="14"/> 查询</button></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>分类名称</th><th>类型</th><th>排序</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><b>{{ row.name }}</b></td><td>{{ row.type===1?'菜品分类':'套餐分类' }}</td><td>{{ row.sort }}</td><td><span :class="['status-chip',row.status?'status-chip--open':'status-chip--closed']">{{ row.status?'启用':'停用' }}</span></td><td class="table-actions"><button class="text-link" @click="openCategory(row)">编辑</button><button class="text-link" @click="toggleCategory(row)">{{ row.status?'停用':'启用' }}</button><button class="text-link text-link--danger" @click="deleteCategory(row)">删除</button></td></tr></tbody></table></div><div v-if="!rows.length" class="quiet-empty"><b>还没有分类</b><small>新增分类后，再添加鲜品或套餐。</small></div><div class="pagination"><span>共 {{ total }} 条</span><button :disabled="page<=1" @click="page--;loadPane()">上一页</button><span>{{ page }}</span><button :disabled="page*pageSize>=total" @click="page++;loadPane()">下一页</button></div></section>
        </template>

        <template v-else-if="pane==='goods'">
          <section class="admin-panel module-panel"><div class="module-toolbar"><div class="filter-row"><label>菜品名称<input v-model="filters.dishName" placeholder="输入菜品名称" @keyup.enter="page=1;loadPane()"/></label><label>分类<select v-model="filters.dishCategoryId"><option value="">全部分类</option><option v-for="item in categories" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>状态<select v-model="filters.dishStatus"><option value="">全部</option><option value="1">起售</option><option value="0">停售</option></select></label><button class="btn btn--soft btn--sm" @click="page=1;loadPane()"><Search :size="14"/> 筛选</button></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>菜品</th><th>分类</th><th>价格</th><th>口味规格</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><span class="goods-cell"><img :src="row.image||'/fresh-harvest-hero.png'" :alt="row.name" @error="adminImageError($event,row.name)"/><b>{{ row.name }}</b></span></td><td>{{ row.categoryName||categories.find(c=>Number(c.id)===Number(row.categoryId))?.name||'—' }}</td><td>¥{{ fmt(row.price) }}</td><td>{{ (row.flavors||[]).map(f=>f.name).join('、')||'标准规格' }}</td><td><span :class="['status-chip',row.status?'status-chip--open':'status-chip--closed']">{{ row.status?'起售中':'已停售' }}</span></td><td class="table-actions"><button class="text-link" @click="editDish(row)">编辑</button><button class="text-link" @click="toggleDish(row)">{{ row.status?'停售':'起售' }}</button><button class="text-link text-link--danger" @click="deleteDish(row)">删除</button></td></tr></tbody></table></div><div v-if="!rows.length" class="quiet-empty"><b>还没有菜品</b><small>添加菜品并上传图片，顾客端就能看到。</small></div><div class="pagination"><span>共 {{ total }} 条</span><button :disabled="page<=1" @click="page--;loadPane()">上一页</button><span>{{ page }}</span><button :disabled="page*pageSize>=total" @click="page++;loadPane()">下一页</button></div></section>
        </template>

        <template v-else-if="pane==='setmeals'">
          <section class="admin-panel module-panel"><div class="module-toolbar"><div class="filter-row"><label>套餐名称<input v-model="filters.mealName" placeholder="输入套餐名称" @keyup.enter="page=1;loadPane()"/></label><label>分类<select v-model="filters.mealCategoryId"><option value="">全部分类</option><option v-for="item in mealCategories" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>状态<select v-model="filters.mealStatus"><option value="">全部</option><option value="1">起售</option><option value="0">停售</option></select></label><button class="btn btn--soft btn--sm" @click="page=1;loadPane()"><Search :size="14"/> 筛选</button></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>套餐</th><th>分类</th><th>售价</th><th>包含菜品</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><span class="goods-cell"><img :src="row.image||'/fresh-harvest-hero.png'" :alt="row.name" @error="adminImageError($event,row.name)"/><b>{{ row.name }}</b></span></td><td>{{ row.categoryName||mealCategories.find(c=>Number(c.id)===Number(row.categoryId))?.name||'—' }}</td><td>¥{{ fmt(row.price) }}</td><td>{{ (row.setmealDishes||[]).length }} 款菜品</td><td><span :class="['status-chip',row.status?'status-chip--open':'status-chip--closed']">{{ row.status?'起售中':'已停售' }}</span></td><td class="table-actions"><button class="text-link" @click="editMeal(row)">编辑</button><button class="text-link" @click="toggleMeal(row)">{{ row.status?'停售':'起售' }}</button><button class="text-link text-link--danger" @click="deleteMeal(row)">删除</button></td></tr></tbody></table></div><div v-if="!rows.length" class="quiet-empty"><b>还没有套餐</b><small>组合门店在售菜品，制作专属鲜食套餐。</small></div><div class="pagination"><span>共 {{ total }} 条</span><button :disabled="page<=1" @click="page--;loadPane()">上一页</button><span>{{ page }}</span><button :disabled="page*pageSize>=total" @click="page++;loadPane()">下一页</button></div></section>
        </template>

        <template v-else-if="pane==='customers'">
          <section class="admin-panel module-panel">
            <div class="module-toolbar"><div class="filter-row"><label>客户姓名<input v-model.trim="filters.customerName" placeholder="按姓名筛选" @keyup.enter="page=1;loadPane()"/></label><label>手机号<input v-model.trim="filters.customerPhone" placeholder="按手机号筛选" @keyup.enter="page=1;loadPane()"/></label><button class="btn btn--soft btn--sm" @click="page=1;loadPane()"><Search :size="14"/> 查询客户</button><small class="subtle-copy">客户首次微信登录后自动建立档案</small></div></div>
            <div class="table-scroll"><table class="data-table"><thead><tr><th>客户编号</th><th>客户姓名</th><th>手机号</th><th>性别</th><th>建档时间</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>#{{ row.id }}</td><td><b>{{ row.name||'微信顾客' }}</b></td><td>{{ row.phone||'未填写' }}</td><td>{{ row.sex==='1'?'男':row.sex==='0'?'女':'—' }}</td><td>{{ row.createTime?new Date(row.createTime).toLocaleString('zh-CN'):'—' }}</td></tr></tbody></table></div>
            <div v-if="!rows.length" class="quiet-empty"><b>暂时没有匹配的客户档案</b><small>新客户首次登录后会自动注册并出现在这里。</small></div>
            <div class="pagination"><span>共 {{ total }} 位客户</span><button :disabled="page<=1" @click="page--;loadPane()">上一页</button><span>{{ page }}</span><button :disabled="page*pageSize>=total" @click="page++;loadPane()">下一页</button></div>
          </section>
        </template>

        <template v-else-if="pane==='employees'">
          <section class="admin-panel module-panel"><div class="module-toolbar"><div class="filter-row"><label>员工姓名<input v-model="filters.employeeName" placeholder="输入员工姓名" @keyup.enter="page=1;loadPane()"/></label><button class="btn btn--soft btn--sm" @click="page=1;loadPane()"><Search :size="14"/> 查询</button></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>账号</th><th>姓名</th><th>手机号</th><th>性别</th><th>身份证号</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ row.username }}</td><td><b>{{ row.name }}</b></td><td>{{ row.phone||'—' }}</td><td>{{ row.sex==='1'?'男':row.sex==='0'?'女':'—' }}</td><td>{{ row.idNumber||'—' }}</td><td><span :class="['status-chip',row.status?'status-chip--open':'status-chip--closed']">{{ row.status?'正常':'已禁用' }}</span></td><td class="table-actions"><button class="text-link" @click="editEmployee(row)">编辑</button><button class="text-link" @click="toggleEmployee(row)">{{ row.status?'禁用':'启用' }}</button></td></tr></tbody></table></div><div v-if="!rows.length" class="quiet-empty"><b>没有匹配的员工</b><small>可新增员工或更改姓名筛选。</small></div><div class="pagination"><span>共 {{ total }} 条</span><button :disabled="page<=1" @click="page--;loadPane()">上一页</button><span>{{ page }}</span><button :disabled="page*pageSize>=total" @click="page++;loadPane()">下一页</button></div></section>
        </template>

        <template v-else-if="pane==='orders'">
          <div class="stats-grid stats-grid--compact"><button class="stat-card stat-card--link" @click="filters.orderStatus='2';page=1;loadPane()"><span>待接单</span><strong>{{ s.orderStats.toBeConfirmed||0 }}</strong><small>顾客已付款</small></button><button class="stat-card stat-card--link" @click="filters.orderStatus='3';page=1;loadPane()"><span>待配送</span><strong>{{ s.orderStats.confirmed||0 }}</strong><small>门店已接单</small></button><button class="stat-card stat-card--link" @click="filters.orderStatus='4';page=1;loadPane()"><span>配送中</span><strong>{{ s.orderStats.deliveryInProgress||0 }}</strong><small>等待顾客签收</small></button><button class="stat-card stat-card--link" @click="resetOrderFilters();page=1;loadPane()"><span>全部订单</span><strong>{{ total }}</strong><small>查看记录</small></button></div>
          <section class="admin-panel module-panel"><div class="module-toolbar"><div class="filter-row"><label>订单号<input v-model="filters.orderNumber" placeholder="订单编号"/></label><label>手机号<input v-model="filters.phone" placeholder="顾客手机号"/></label><label>状态<select v-model="filters.orderStatus"><option value="">全部状态</option><option v-for="(name,id) in orderLabels" :key="id" :value="String(id)">{{ name }}</option></select></label><label>开始时间<input v-model="filters.beginTime" type="datetime-local"/></label><label>结束时间<input v-model="filters.endTime" type="datetime-local"/></label><button class="btn btn--soft btn--sm" @click="page=1;loadPane()"><Search :size="14"/> 查询</button><button class="btn btn--bare btn--sm" @click="Object.assign(filters,{orderNumber:'',phone:'',orderStatus:'',beginTime:'',endTime:''});page=1;loadPane()">重置</button></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>订单 / 时间</th><th>顾客</th><th>商品</th><th>金额</th><th>状态</th><th>订单操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><b>{{ orderNo(row) }}</b><small class="table-sub">{{ String(row.orderTime||'').replace('T',' ').slice(0,16) }}</small></td><td>{{ row.consignee||'顾客' }}<small class="table-sub">{{ row.phone||'' }}</small></td><td class="ellipsis-cell">{{ itemSummary(row) }}</td><td>¥{{ fmt(row.amount) }}</td><td><span :class="['status-chip',row.status===6||row.status===7?'status-chip--closed':'status-chip--open']">{{ orderLabels[row.status]||'处理中' }}</span></td><td class="table-actions"><button class="text-link" @click="orderDetails(row)">详情</button><button v-if="row.status===2" class="text-link" @click="requestOrderAction(row,'confirm')">接单</button><button v-if="row.status===2" class="text-link text-link--danger" @click="requestOrderAction(row,'reject')">拒单</button><button v-if="row.status===3" class="text-link" @click="requestOrderAction(row,'delivery')">开始配送</button><button v-if="row.status===4" class="text-link" @click="requestOrderAction(row,'complete')">完成</button><button v-if="[1,2,3].includes(row.status)" class="text-link text-link--danger" @click="requestOrderAction(row,'cancel')">取消</button></td></tr></tbody></table></div><div v-if="!rows.length" class="quiet-empty"><b>没有符合条件的订单</b><small>更改筛选条件或等待新订单。</small></div><div class="pagination"><span>共 {{ total }} 条</span><button :disabled="page<=1" @click="page--;loadPane()">上一页</button><span>{{ page }}</span><button :disabled="page*pageSize>=total" @click="page++;loadPane()">下一页</button></div></section>
        </template>

        <template v-else-if="pane==='sales'">
          <section class="admin-panel module-panel"><div class="panel-heading"><div><span class="eyebrow">FLASH SALE · 鲜选有度</span><h2>限时特卖活动</h2></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>活动</th><th>商品 / 时间</th><th>特卖价</th><th>库存</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><b>{{ row.activityName }}</b></td><td>{{ row.dishName }}<small class="table-sub">{{ row.startTime }} — {{ row.endTime }}</small></td><td>¥{{ fmt(row.salePrice) }}<small class="table-sub">原价 ¥{{ fmt(row.originalPrice) }}</small></td><td>{{ row.availableStock??row.stock }} / {{ row.stock }}</td><td><span :class="['status-chip',row.status?'status-chip--open':'status-chip--closed']">{{ row.status?'进行中':'未启用' }}</span></td><td class="table-actions"><button class="text-link" @click="editSale(row)">编辑</button><button class="text-link" @click="toggleSale(row)">{{ row.status?'停用':'启用' }}</button><button class="text-link" @click="preheatSale(row)">准备库存</button></td></tr></tbody></table></div><div v-if="!rows.length" class="quiet-empty"><b>还没有特卖活动</b><small>创建活动并启用后，顾客即可参与限时抢购。</small><button class="btn btn--primary btn--sm" @click="openSale()">创建首场活动</button></div><div class="pagination"><span>共 {{ total }} 条</span><button :disabled="page<=1" @click="page--;loadPane()">上一页</button><span>{{ page }}</span><button :disabled="page*pageSize>=total" @click="page++;loadPane()">下一页</button></div></section>
        </template>

        <template v-else-if="pane==='reports'">
          <section class="admin-panel module-panel"><div class="module-toolbar"><div class="filter-row"><label>开始日期<input v-model="reportRange.begin" type="date"/></label><label>结束日期<input v-model="reportRange.end" type="date"/></label><button class="btn btn--soft btn--sm" @click="loadPane()"><CalendarDays :size="14"/> 查询区间</button><button v-if="s.mode==='live'" class="btn btn--primary btn--sm" @click="exportReport"><Download :size="14"/> 导出报表</button></div></div><div class="report-kpis"><div><small>营业额</small><b>¥{{ fmt(reportData.turnover?.turnoverList?split(reportData.turnover.turnoverList).reduce((a,b)=>a+b,0):0) }}</b></div><div><small>总订单</small><b>{{ reportData.orders?.totalOrderCount||0 }}</b></div><div><small>有效订单</small><b>{{ reportData.orders?.validOrderCount||0 }}</b></div><div><small>完成率</small><b>{{ Math.round((reportData.orders?.orderCompletionRate||0)*100) }}%</b></div></div><div class="report-grid"><article class="report-chart"><span class="eyebrow">TURNOVER</span><h3>每日营业额</h3><svg viewBox="0 0 600 120" role="img" aria-label="营业额趋势"><polyline :points="points(reportSeries.turnover)" fill="none" stroke="#4f8159" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="chart-labels"><span v-for="day in reportDates" :key="day">{{ day.slice(5) }}</span></div></article><article class="report-chart"><span class="eyebrow">ORDERS</span><h3>订单趋势</h3><svg viewBox="0 0 600 120" role="img" aria-label="订单趋势"><polyline :points="points(reportSeries.orders)" fill="none" stroke="#c98a45" stroke-width="3" stroke-linecap="round"/></svg><div class="chart-labels"><span v-for="day in reportDates" :key="day">{{ day.slice(5) }}</span></div></article><article class="report-chart"><span class="eyebrow">NEW CUSTOMERS</span><h3>新增用户</h3><svg viewBox="0 0 600 120" role="img" aria-label="新增用户"><polyline :points="points(reportSeries.users)" fill="none" stroke="#718c9d" stroke-width="3" stroke-linecap="round"/></svg><div class="chart-labels"><span v-for="day in reportDates" :key="day">{{ day.slice(5) }}</span></div></article><article class="report-chart report-rank"><span class="eyebrow">TOP 10</span><h3>热销商品</h3><div v-for="(item,index) in topRows.slice(0,10)" :key="item.name" class="rank-row"><i>{{ index+1 }}</i><span>{{ item.name }}</span><b>{{ item.value }} 份</b></div><p v-if="!topRows.length" class="subtle-copy">选择日期后查看商品排名。</p></article></div></section>
        </template>

        <template v-else-if="pane==='assistant'">
          <div class="assistant-layout"><section class="assistant-intro"><span class="assistant-mark"><Sparkles :size="22"/></span><span class="eyebrow">XIANJI OPERATIONS COPILOT</span><h2>让经营数据，<br/>变成下一步行动。</h2><p>汇总营业额、销售趋势、品类贡献、商品排行与订单状态，并给出经营建议。</p><label>分析区间<div class="filter-row"><input v-model="reportRange.begin" type="date"/><span>至</span><input v-model="reportRange.end" type="date"/></div></label><label>经营问题<textarea v-model="agent.query" rows="4" maxlength="500" placeholder="例如：今天哪类商品卖得最好？订单取消率是否异常？"/></label><button class="btn btn--primary" :disabled="agent.loading||!agent.query.trim()" @click="analyze"><Sparkles v-if="!agent.loading" :size="16"/><RotateCw v-else :size="16" class="spin"/> 生成分析</button><p class="subtle-copy">演示体验使用样例数据；连接门店数据后可生成实时建议。</p></section><section class="assistant-results"><div v-if="agent.error" class="admin-alert"><CircleAlert :size="16"/>{{ agent.error }}</div><template v-if="agent.result"><span class="eyebrow">经营分析</span><h2>{{ agent.result.summary }}</h2><div v-if="agent.result.analysis?.length"><h3>经营观察</h3><p v-for="line in agent.result.analysis" :key="line">{{ line }}</p></div><div v-if="agent.result.suggestions?.length"><h3>建议动作</h3><p v-for="line in agent.result.suggestions" :key="line" class="suggestion-line"><ArrowRight :size="14"/>{{ line }}</p></div></template><div v-else class="quiet-empty"><span class="quiet-empty__icon"><Sparkles :size="20"/></span><b>等你提出第一个经营问题</b><small>试试询问销售趋势、品类结构或订单状态。</small></div></section></div>
        </template>
      </div>
    </main>

    <Sheet :open="dialog==='category'" :title="categoryForm.id?'编辑商品分类':'新增商品分类'" size="small" @close="dialog=''"><form class="activity-form module-form" @submit.prevent="saveCategory"><label>分类类型<select v-model.number="categoryForm.type"><option :value="1">菜品分类</option><option :value="2">套餐分类</option></select></label><label>分类名称<input v-model.trim="categoryForm.name" required minlength="2" maxlength="20" placeholder="例如：应季鲜果"/></label><label>显示顺序<input v-model.number="categoryForm.sort" type="number" min="1" required/></label><button class="btn btn--primary activity-submit"><Check :size="16"/> 保存分类</button></form></Sheet>
    <Sheet :open="dialog==='dish'" :title="dishForm.id?'编辑菜品':'添加菜品'" size="medium" @close="dialog=''"><form class="activity-form module-form" @submit.prevent="saveDish"><label>菜品名称<input v-model.trim="dishForm.name" required maxlength="20" placeholder="例如：晨采红颜草莓"/></label><div class="form-double"><label>商品分类<select v-model="dishForm.categoryId" required><option value="" disabled>选择分类</option><option v-for="item in categories" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>售价（元）<input v-model.number="dishForm.price" type="number" min="0.01" step="0.01" required/></label></div><label>销售规格<input v-model.trim="dishForm.unit" required maxlength="32" placeholder="如：500g / 份"/></label><label>商品图片地址<input v-model.trim="dishForm.image" type="text" placeholder="粘贴图片地址，或使用匹配配图"/></label><button class="text-link admin-use-generated" type="button" :disabled="!hasProductImage(dishForm.name)" @click="applyGeneratedDishImage">使用匹配配图</button><label class="upload-box"><ImagePlus :size="17"/> 上传商品图片<input type="file" accept="image/*" @change="uploadDishImage"/></label><img v-if="dishForm.image" class="form-image-preview" :src="dishForm.image" alt="菜品图片预览" @error="adminImageError($event,dishForm.name)"/><label>商品描述<textarea v-model.trim="dishForm.description" rows="3" maxlength="200" placeholder="描述产地、口感和规格"/></label><label>规格口味<textarea v-model="dishForm.flavorsText" rows="3" placeholder="每行一个，格式：规格=小份,大份"/></label><button class="btn btn--primary activity-submit" :disabled="busy"><Check :size="16"/> 保存菜品</button></form></Sheet>
    <Sheet :open="dialog==='meal'" :title="mealForm.id?'编辑套餐':'添加套餐'" size="medium" @close="dialog=''"><form class="activity-form module-form" @submit.prevent="saveMeal"><label>套餐名称<input v-model.trim="mealForm.name" required maxlength="20"/></label><div class="form-double"><label>套餐分类<select v-model="mealForm.categoryId" required><option value="" disabled>选择分类</option><option v-for="item in mealCategories" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>套餐售价（单品合计 95 折）<input :value="mealSalePrice.toFixed(2)" readonly/><small>食材单品合计 ¥{{ fmt(mealListPrice) }}，套餐价自动计算。</small></label></div><label>套餐图片 URL<input v-model.trim="mealForm.image" type="url" placeholder="可填写已上传图片地址"/></label><label class="upload-box"><ImagePlus :size="17"/> 上传套餐图片<input type="file" accept="image/*" @change="uploadMealImage"/></label><img v-if="mealForm.image" class="form-image-preview" :src="mealForm.image" alt="套餐图片预览" @error="adminImageError($event,mealForm.name)"/><label>套餐描述<textarea v-model.trim="mealForm.description" rows="2" maxlength="200"/></label><fieldset class="dish-picker"><legend>组合生鲜食材（勾选并设置份数）</legend><label v-for="dish in dishes" :key="dish.id" class="dish-picker__row"><input v-model="mealForm.dishIds" type="checkbox" :value="dish.id"/><span>{{ dish.name }} · ¥{{ fmt(dish.price) }}</span><input v-if="mealForm.dishIds.includes(dish.id)" v-model.number="mealForm.copies[dish.id]" type="number" min="1" max="99" aria-label="菜品份数"/></label></fieldset><button class="btn btn--primary activity-submit"><Check :size="16"/> 保存套餐</button></form></Sheet>
    <Sheet :open="dialog==='employee'" :title="employeeForm.id?'编辑员工':'新增员工'" size="small" @close="dialog=''"><form class="activity-form module-form" @submit.prevent="saveEmployee"><label>登录账号<input v-model.trim="employeeForm.username" required minlength="2" maxlength="20"/></label><label>员工姓名<input v-model.trim="employeeForm.name" required minlength="2" maxlength="12"/></label><label>手机号<input v-model.trim="employeeForm.phone" required pattern="1[3-9][0-9]{9}" maxlength="11"/></label><label>性别<select v-model="employeeForm.sex"><option value="1">男</option><option value="0">女</option></select></label><label>身份证号<input v-model.trim="employeeForm.idNumber" required minlength="18" maxlength="18"/></label><p class="form-tip">新增员工登录后，请及时修改初始密码。</p><button class="btn btn--primary activity-submit"><Check :size="16"/> 保存员工</button></form></Sheet>
    <Sheet :open="dialog==='sale'" :title="saleForm.id?'编辑特卖活动':'创建限时特卖'" size="medium" @close="dialog=''"><form class="activity-form module-form" @submit.prevent="saveSale"><label>活动名称<input v-model.trim="saleForm.activityName" required maxlength="64"/></label><label>关联菜品<select v-model="saleForm.dishId" required><option value="" disabled>选择在售菜品</option><option v-for="dish in dishes.filter(item=>item.status===1)" :key="dish.id" :value="dish.id">{{ dish.name }} · ¥{{ fmt(dish.price) }}</option></select></label><div class="form-double"><label>特卖价（元）<input v-model.number="saleForm.salePrice" type="number" min="0.01" step="0.01" required/></label><label>库存<input v-model.number="saleForm.stock" type="number" min="1" max="10000" required/></label></div><div class="form-double"><label>开始时间<input v-model="saleForm.startTime" type="datetime-local" required/></label><label>结束时间<input v-model="saleForm.endTime" type="datetime-local" required/></label></div><label>每人限购<input v-model.number="saleForm.limitPerUser" type="number" min="1" max="100" required/></label><button class="btn btn--primary activity-submit"><Check :size="16"/> 保存活动</button></form></Sheet>
    <Sheet :open="dialog==='orderReason'" :title="pendingAction==='reject'?'填写拒单原因':'填写取消原因'" size="small" @close="dialog=''"><form class="activity-form module-form" @submit.prevent="submitReason"><label>原因说明<textarea v-model.trim="orderReason" required maxlength="200" rows="4" placeholder="请填写原因，方便顾客理解"/></label><button class="btn btn--primary activity-submit"><Check :size="16"/> 确认提交</button></form></Sheet>
    <Sheet :open="dialog==='orderDetail'" title="订单详情" size="medium" @close="dialog=''"><div v-if="detailOrder" class="order-detail-view"><div class="detail-hero"><span class="status-pip"/><b>{{ orderLabels[detailOrder.status]||'订单处理中' }}</b><small>{{ orderNo(detailOrder) }} · {{ detailOrder.orderTime }}</small></div><div class="detail-block"><h3>顾客与配送</h3><p>{{ detailOrder.consignee }} · {{ detailOrder.phone }}</p><p>{{ detailOrder.address||detailOrder.addressBook?.detail||'到店自取' }}</p><p>备注：{{ detailOrder.remark||'无' }}</p></div><div class="detail-block"><h3>商品清单</h3><div v-for="item in detailOrder.orderDetailList||[]" :key="item.id||item.name" class="detail-line"><span>{{ item.name }} × {{ item.number }}</span><b>¥{{ fmt(item.amount*item.number) }}</b></div></div><div class="detail-total">订单金额 <b>¥{{ fmt(detailOrder.amount) }}</b></div><div class="detail-actions"><button v-if="detailOrder.status===2" class="btn btn--primary btn--sm" @click="performOrderAction(detailOrder,'confirm')">接单备货</button><button v-if="detailOrder.status===3" class="btn btn--primary btn--sm" @click="performOrderAction(detailOrder,'delivery')">开始配送</button><button v-if="detailOrder.status===4" class="btn btn--primary btn--sm" @click="performOrderAction(detailOrder,'complete')">完成订单</button></div></div></Sheet>
  </div>
</template>
